145	export const publishNewRelation = async (
146	  plugin: DiscourseGraphPlugin,
147	  relation: RelationInstance,
148	): Promise<boolean> => {
149	  const client = await getLoggedInClient(plugin);
150	  if (!client) throw new Error("Cannot get client");
151	  const context = await getSupabaseContext(plugin);
152	  if (!context) throw new Error("Cannot get context");
153	  const sourceFile = getFileForNodeInstanceId(plugin, relation.source);
154	  const destinationFile = getFileForNodeInstanceId(
155	    plugin,
156	    relation.destination,
157	  );
158	  if (!sourceFile || !destinationFile) return false;
159	  const sourceFm =
160	    plugin.app.metadataCache.getFileCache(sourceFile)?.frontmatter;
161	  const destinationFm =
162	    plugin.app.metadataCache.getFileCache(destinationFile)?.frontmatter;
163	  if (!sourceFm || !destinationFm) return false;
164	
165	  const relationTriples = plugin.settings.discourseRelations ?? [];
166	  const triple = relationTriples.find(
167	    (triple) =>
168	      triple.relationshipTypeId === relation.type &&
169	      triple.sourceId === sourceFm.nodeTypeId &&
170	      triple.destinationId === destinationFm.nodeTypeId,
171	  );
172	  if (!triple) return false;
173	  if (isProvisionalSchema(triple)) return false;
174	  const relationType = plugin.settings.relationTypes.find(
175	    (rt) => rt.id === relation.type,
176	  );
177	  if (relationType && isProvisionalSchema(relationType)) return false;
178	  if (relation.tentative === false) return false;
179	  const resourceIds = [relation.id, relation.type, triple.id];
180	  const { source: sourceGroups, destination: destinationGroups } =
181	    await getPublishedGroupsByNode({
182	      client,
183	      frontmatterByNode: { source: sourceFm, destination: destinationFm },
184	    });
185	  if (!sourceGroups.size || !destinationGroups.size) return false;
186	  const myGroups = await getAvailableGroupIds(client);
187	  const targetGroups = await getGroupIdsWithSpaceAccess({
188	    client,
189	    spaceId: context.spaceId,
190	    groupIds: [
191	      ...intersection(
192	        new Set(myGroups),
193	        intersection(sourceGroups, destinationGroups),
194	      ),
195	    ],
196	  });
197	  if (!targetGroups.size) return false;
198	  // in that case, sync all relations (only) before publishing
199	  await syncAllNodesAndRelations(plugin, context, true);
200	  const entries = [];
201	  for (const group of targetGroups) {
202	    for (const id of resourceIds) {
203	      entries.push({
204	        account_uid: group,
205	        source_local_id: id,
206	        space_id: context.spaceId,
207	      });
208	    }
209	  }
210	  const publishResponse = await client
211	    .from("ResourceAccess")
212	    .upsert(entries, { ignoreDuplicates: true });
213	  if (publishResponse.error && publishResponse.error.code !== "23505")
214	    throw publishResponse.error;
215	  relation.publishedToGroupId = [
216	    ...new Set([
217	      ...(relation.publishedToGroupId || []),
218	      ...targetGroups.values(),
219	    ]).values(),
220	  ];
221	  return true;
222	};
