224	export const publishNodeRelations = async ({
225	  plugin,
226	  client,
227	  nodeId,
228	  myGroup,
229	  spaceId,
230	}: {
231	  plugin: DiscourseGraphPlugin;
232	  client: DGSupabaseClient;
233	  nodeId: string;
234	  myGroup: string;
235	  spaceId: number;
236	}): Promise<void> => {
237	  const relations = (
238	    await getRelationsForNodeInstanceId(plugin, nodeId)
239	  ).filter((relation) => !relation.importedFromRid);
240	  const resourceIds: Set<string> = new Set();
241	  const relationTriples = plugin.settings.discourseRelations ?? [];
242	  const relevantNodeIds: Set<string> = new Set();
243	  relations.map((relation) => {
244	    relevantNodeIds.add(relation.source);
245	    relevantNodeIds.add(relation.destination);
246	  });
247	  const relevantNodeFiles = getFileForNodeInstanceIds(plugin, relevantNodeIds);
248	  const frontmatterById: Record<string, FrontMatterCache> = {};
249	  Object.entries(relevantNodeFiles).map(([id, file]: [string, TFile]) => {
250	    const fm = plugin.app.metadataCache.getFileCache(file)?.frontmatter;
251	    if (fm !== undefined) frontmatterById[id] = fm;
252	  });
253	  // The current node's frontmatter does not list myGroup yet.
254	  const otherNodeFrontmatterById = Object.fromEntries(
255	    Object.entries(frontmatterById).filter(
256	      ([, fm]) => fm.nodeInstanceId !== nodeId,
257	    ),
258	  );
259	  const groupsByOtherNodeId = await getPublishedGroupsByNode({
260	    client,
261	    frontmatterByNode: otherNodeFrontmatterById,
262	  });
263	  const relevantNodeTypeById: Record<string, string | undefined> = {};
264	  Object.entries(frontmatterById).map(([id, fm]) => {
265	    if (fm.nodeInstanceId !== nodeId && !groupsByOtherNodeId[id]?.has(myGroup))
266	      return;
267	    relevantNodeTypeById[id] = fm.nodeTypeId as string;
268	  });
269	  relations.map((relation) => {
270	    if ((relation.publishedToGroupId ?? []).includes(myGroup)) return;
271	    const triple = relationTriples.find(
272	      (triple) =>
273	        triple.relationshipTypeId === relation.type &&
274	        triple.sourceId === relevantNodeTypeById[relation.source] &&
275	        triple.destinationId === relevantNodeTypeById[relation.destination],
276	    );
277	    if (triple) {
278	      resourceIds.add(relation.id);
279	      resourceIds.add(relation.type);
280	      resourceIds.add(triple.id);
281	    }
282	  });
283	  if (resourceIds.size === 0) return;
284	  const publishResponse = await client.from("ResourceAccess").upsert(
285	    [...resourceIds.values()].map((sourceLocalId: string) => ({
286	      account_uid: myGroup,
287	      source_local_id: sourceLocalId,
288	      space_id: spaceId,
289	    })),
290	    { ignoreDuplicates: true },
291	  );
292	  if (publishResponse.error && publishResponse.error.code !== "23505")
293	    throw publishResponse.error;
294	  const relData = await loadRelations(plugin);
295	  let dataChanged = false;
296	  relations
297	    .filter((rel) => resourceIds.has(rel.id))
298	    .map((rel) => {
299	      const savedRel = relData.relations[rel.id];
300	      if (!savedRel) return;
301	      const publishedTo = savedRel.publishedToGroupId;
302	      if (!publishedTo) {
303	        savedRel.publishedToGroupId = [myGroup];
304	        dataChanged = true;
305	      } else if (!publishedTo.includes(myGroup)) {
306	        publishedTo.push(myGroup);
307	        dataChanged = true;
308	      }
309	    });
310	  if (dataChanged) await saveRelations(plugin, relData);
311	};
