313	export const publishNode = async ({
314	  plugin,
315	  file,
316	  frontmatter,
317	  groupId,
318	}: {
319	  plugin: DiscourseGraphPlugin;
320	  file: TFile;
321	  frontmatter: FrontMatterCache;
322	  groupId?: string;
323	}): Promise<void> => {
324	  const client = await getLoggedInClient(plugin);
325	  if (!client) throw new Error("Cannot get client");
326	  const myGroups = new Set(await getAvailableGroupIds(client));
327	  if (myGroups.size === 0) throw new Error("Cannot get group");
328	  const existingPublish =
329	    (frontmatter.publishedToGroups as undefined | string[]) || [];
330	  // Hopefully temporary workaround for sync bug
331	  await syncAllNodesAndRelations(plugin);
332	  const commonGroups = existingPublish.filter((g) => myGroups.has(g));
333	  const myGroup =
334	    groupId ?? (commonGroups.length > 0 ? commonGroups : [...myGroups])[0]!;
335	  if (!myGroups.has(myGroup)) {
336	    throw new Error("You are not a member of that group");
337	  }
338	  return await publishNodeToGroup({ plugin, file, frontmatter, myGroup });
339	};

