341	export const ensurePublishedRelationsAccuracy = async ({
342	  client,
343	  context,
344	  plugin,
345	  allNodesById,
346	  relationInstancesData,
347	}: {
348	  client: DGSupabaseClient;
349	  context: SupabaseContext;
350	  plugin: DiscourseGraphPlugin;
351	  allNodesById: Record<string, DiscourseNodeInVault>;
352	  relationInstancesData: RelationsFile;
353	}): Promise<void> => {
354	  const myGroups = await getAvailableGroupIds(client);
355	  const relationInstances = Object.values(relationInstancesData.relations);
356	  const syncedRelationIdsResult = await client
357	    .from("Concept")
358	    .select("source_local_id")
359	    .eq("space_id", context.spaceId)
360	    .eq("is_schema", false)
361	    .eq("is_relation", true);
362	  if (syncedRelationIdsResult.error) {
363	    console.error(
364	      "Could not get synced relation ids",
365	      syncedRelationIdsResult.error,
366	    );
367	    return;
368	  }
369	  const syncedRelationIds = new Set(
370	    (syncedRelationIdsResult.data || []).map((x) => x.source_local_id!),
371	  );
372	  // Also a good time to look at orphan relations
373	  const existingRelationIds = new Set(relationInstances.map((r) => r.id));
374	  const orphanRelationIds = difference(syncedRelationIds, existingRelationIds);
375	  if (orphanRelationIds.size) {
376	    const r = await client
377	      .from("Concept")
378	      .delete()
379	      .eq("space_id", context.spaceId)
380	      .in("source_local_id", [...orphanRelationIds]);
381	    if (!r.error) {
382	      for (const id of orphanRelationIds) {
383	        syncedRelationIds.delete(id);
384	      }
385	    }
386	  }
387	  const ownRelations = relationInstances.filter(
388	    (r) => !r.importedFromRid && syncedRelationIds.has(r.id),
389	  );
390	  let groupsByNodeId: Record<string, Set<string>>;
391	  try {
392	    groupsByNodeId = await getPublishedGroupsByNode({
393	      client,
394	      frontmatterByNode: Object.fromEntries(
395	        ownRelations
396	          .flatMap((r) => [r.source, r.destination])
397	          .flatMap((id) => {
398	            const frontmatter = allNodesById[id]?.frontmatter;
399	            return frontmatter ? [[id, frontmatter]] : [];
400	          }),
401	      ),
402	    });
403	  } catch (error) {
404	    // Going on without these groups would delete valid grants. Local-only
405	    // relations are not reconciled either; the next full sync recovers.
406	    console.error("Could not get the groups of imported nodes", error);
407	    return;
408	  }
409	  let changed = false;
410	  const missingPublishRecords: TablesInsert<"ResourceAccess">[] = [];
411	  for (const group of myGroups) {
412	    const publishableRelations = ownRelations.filter(
413	      (r) =>
414	        groupsByNodeId[r.source]?.has(group) &&
415	        groupsByNodeId[r.destination]?.has(group),
416	    );
417	    const publishableRelationIds = new Set(
418	      publishableRelations.map((x) => x.id),
419	    );
420	    const publishedIds = await client
421	      .from("ResourceAccess")
422	      .select("source_local_id")
423	      .eq("account_uid", group)
424	      .eq("space_id", context.spaceId);
425	    if (publishedIds.error) {
426	      console.error("Could not get synced relation ids", publishedIds.error);
427	      continue;
428	    }
429	    const publishedRelationIds = intersection(
430	      syncedRelationIds,
431	      new Set((publishedIds.data || []).map((x) => x.source_local_id)),
432	    );
433	    const missingPublishableIds = difference(
434	      publishableRelationIds,
435	      publishedRelationIds,
436	    );
437	    if (missingPublishableIds.size > 0) {
438	      missingPublishRecords.push(
439	        ...[...missingPublishableIds].map((source_local_id) => ({
440	          source_local_id,
441	          space_id: context.spaceId,
442	          account_uid: group,
443	        })),
444	      );
445	    }
446	    const extraPublishableIds = difference(
447	      publishedRelationIds,
448	      publishableRelationIds,
449	    );
450	    if (extraPublishableIds.size > 0) {
451	      const r = await client
452	        .from("ResourceAccess")
453	        .delete()
454	        .eq("account_uid", group)
455	        .eq("space_id", context.spaceId)
456	        .in("source_local_id", [...extraPublishableIds]);
457	      if (r.error) console.error(r.error);
458	      else {
459	        for (const id of extraPublishableIds) {
460	          const rel = relationInstancesData.relations[id];
461	          const pos = (rel?.publishedToGroupId || []).indexOf(group);
462	          if (pos >= 0) {
463	            rel!.publishedToGroupId!.splice(pos, 1);
464	            changed = true;
465	          }
466	        }
467	      }
468	    }
469	  }
470	  let groupIdsWithSpaceAccess = new Set<string>();
471	  try {
472	    groupIdsWithSpaceAccess = await getGroupIdsWithSpaceAccess({
473	      client,
474	      spaceId: context.spaceId,
475	      groupIds: [
476	        ...new Set(missingPublishRecords.map((record) => record.account_uid)),
477	      ],
478	    });
479	  } catch (error) {
480	    // No early return: the deletes above still need saving.
481	    console.error("Could not give groups access to the space", error);
482	  }
483	  const publishRecords = missingPublishRecords.filter((record) =>
484	    groupIdsWithSpaceAccess.has(record.account_uid),
485	  );
486	  if (publishRecords.length > 0) {
487	    const r = await client.from("ResourceAccess").upsert(publishRecords);
488	    if (r.error) console.error(r.error);
489	    else {
490	      for (const record of publishRecords) {
491	        const rel = relationInstancesData.relations[record.source_local_id];
492	        const group = record.account_uid;
493	        const pos = (rel?.publishedToGroupId || []).indexOf(group);
494	        if (rel && pos < 0) {
495	          if (rel.publishedToGroupId === undefined) rel.publishedToGroupId = [];
496	          rel.publishedToGroupId.push(group);
497	          changed = true;
498	        }
499	      }
500	    }
501	  }
502	  if (changed) {
503	    await saveRelations(plugin, relationInstancesData);
504	  }
505	};
