562	export const syncAllNodesAndRelations = async (
563	  plugin: DiscourseGraphPlugin,
564	  supabaseContext?: SupabaseContext,
565	  relationsOnly?: boolean,
566	): Promise<void> => {
567	  try {
568	    const context = supabaseContext ?? (await getSupabaseContext(plugin));
569	    if (!context) {
570	      throw new Error("Could not create Supabase context");
571	    }
572	
573	    const supabaseClient = await getLoggedInClient(plugin);
574	    if (!supabaseClient) {
575	      throw new Error("Could not log in to Supabase client");
576	    }
577	
578	    const allNodes = await collectDiscourseNodesFromVault(plugin, true);
579	    const relationInstancesData = await loadRelations(plugin);
580	    const sourceSlotByNodeId = relationsOnly
581	      ? undefined
582	      : indexSourceSlots({
583	          plugin,
584	          nodes: allNodes,
585	          relations: Object.values(relationInstancesData.relations),
586	        });
587	
588	    const { changedNodes: changedNodeInstances } = relationsOnly
589	      ? { changedNodes: [] }
590	      : await buildChangedNodesFromNodes({
591	          nodes: allNodes,
592	          supabaseClient,
593	          context,
594	          fullSync: true,
595	          sourceSlotByNodeId,
596	          nodeTypeIds: new Set(
597	            (plugin.settings.nodeTypes ?? []).map((nodeType) => nodeType.id),
598	          ),
599	        });
600	
601	    const accountLocalId = plugin.settings.accountLocalId;
602	    if (!accountLocalId) {
603	      throw new Error("accountLocalId not found in plugin settings");
604	    }
605	
606	    await upsertNodesToSupabaseAsContentWithEmbeddings({
607	      obsidianNodes: changedNodeInstances,
608	      supabaseClient,
609	      context,
610	      accountLocalId,
611	      plugin,
612	    });
613	
614	    await convertDgToSupabaseConcepts({
615	      nodesSince: changedNodeInstances,
616	      supabaseClient,
617	      context,
618	      plugin,
619	      allNodes,
620	      fullSync: true,
621	      relationInstancesData,
622	      sourceSlotByNodeId,
623	    });
624	
625	    // When synced nodes are already published, ensure non-text assets are in storage.
626	    await syncPublishedNodesAssets(
627	      plugin,
628	      changedNodeInstances.filter((node) => node.changeTypes.length > 0),
629	    );
630	  } catch (error) {
631	    console.error("syncAllNodesAndRelations: Process failed:", error);
632	    throw error;
633	  }
634	};
