662	    await getLastRelationSyncTime(supabaseClient, context.spaceId)
663	  ).getTime();
664	  const nodeTypes = plugin.settings.nodeTypes ?? [];
665	  const relationTypes = (plugin.settings.relationTypes ?? []).filter(
