678	  );
679	
680	  // Missing schemas bypass the modified-time filters below: a refused schema can
681	  // be older than the newest schema the database holds.
682	  const missingSchemaIds = fullSync
683	    ? await deleteStaleSchemasAndFindMissing({
684	        supabaseClient,
685	        spaceId: context.spaceId,
686	        localSchemaIds: [
